css:
body {
    font-family: Arial, sans-serif;
    font-size: 12px;
    color: #000;
}

/* Document Information */
#div_tab {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 12px;
}

#div_tab td {
    padding: 6px 8px;
    border: 1px solid #000;
    vertical-align: middle;
}

#div_tab .label {
    width: 18%;
    font-weight: bold;
}

#div_tab td:nth-child(2) {
    width: 32%;
}

#div_tab td:nth-child(4) {
    width: 32%;
}

/* Item Table */
.table1 {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
    font-size: 11px;
}

.table1 th,
.table1 td {
    border: 1px solid #000;
    padding: 6px 5px;
    text-align: center;
    vertical-align: middle;
}

.table1 th {
    font-weight: bold;
}

.table1 thead {
    display: table-header-group;
}

.table1 tr {
    page-break-inside: avoid;
}

/* Payment Summary */
.summary-table {
    margin-top: 12px;
}


/* Footer */
.footer {
    margin-top: 20px;
    font-size: 10px;
}

.footer hr {
    border: 0;
    border-top: 1px solid #000;
    margin-bottom: 8px;
}

.page-number {
    text-align: center;
    font-size: 10px;
}
.payment-summary {
    width: 100%;
    margin-top: 15px;
    font-size: 12px;
}

.payment-summary div {
    display: inline-block;
    width: 32%;
    vertical-align: top;
}

.payment-summary strong {
    margin-right: 5px;
}
.signature-section {
    width: 100%;
    margin-top: 55px;
    font-size: 12px;
}

.signature-row {
    width: 100%;
    min-height: 30px;
}

.signature-left,
.signature-right {
    display: inline-block;
    width: 49%;
    vertical-align: top;
}

.signature-left {
    text-align: left;
}

.signature-right {
    text-align: center;
}

.approved-row {
    margin-top: 50px;
}
